/* ============================================================
   Fiscalité : déclarations complémentaires reliées à la comptabilité
   3519 (remboursement de crédit de TVA) · 3514 (acomptes de TVA, RSI)
   2571 (acomptes d'IS) · 2572 (solde d'IS) · 2777 (RCM / PFU)
   2561 (IFU) · DAS2 (honoraires) · e-reporting
   Modèles : formulaires de la DGFiP (impots.gouv.fr), copies de
   travail en PDF et Excel, écritures générées dans les journaux.
   ============================================================ */
const F2 = () => (S.fisc2 ||= { remb: {}, tvaAc: {}, isAc: {}, rcm: [], das2: {}, erep: {} });
const f2E = c => eur(c) + " €";
const f2Lib = { tvaRemb: "3519 - Remboursements de TVA", tvaAc: "3514 - Acomptes de TVA", isAc: "2571 - Acomptes d'IS", isSolde: "2572 - Solde d'IS", rcm: "RCM 2777 - PFU", ifu: "2561 - IFU", das2: "DAS2 - Honoraires", ereport: "E-reporting" };
const f2BankJ = () => (journalBy("BQ") || S.journaux.find(j => j.type === "BQ") || { code: "BQ" }).code;
const f2OD = () => (journalBy("OD") || S.journaux.find(j => j.type === "OD") || { code: "OD" }).code;
const f2Tools = k => `<div class="row"><button class="btn" data-act="f2Xls" data-k="${k}">⇩ Excel</button><button class="btn pri" data-act="f2Pdf" data-k="${k}">⇩ PDF</button></div>`;
const f2Head = (k, lead) => `<div class="pg-h"><div><div class="eyebrow">Fiscalité · ${esc(S.nom)}</div><h1>${esc(f2Lib[k])}</h1><p class="lead">${lead}</p></div>${f2Tools(k)}</div>`;
const f2Kpi = L => `<div class="fin-k">${L.map(([l, v, c]) => `<div><span>${l}</span><b class="mono ${c || ""} ${typeof v !== "number" && String(v).length > 22 ? "f2-txt" : ""}">${typeof v === "number" ? eur0(v) : esc(v)}</b></div>`).join("")}</div>`;
const f2Ecr = (o) => { const err = canWriteAt(o.date); if (err) { toast(err); return null; } return addEcr(mkEcr(o)); };
const f2EcrOf = id => id ? E.find(e => e.id === id) : null;
const f2Btn = (e, act, lab, data) => e ? `<a class="lnk" data-act="viewEcr" data-id="${e.id}">✓ écriture du ${frDate(e.date)}</a>` : `<button class="btn sm" data-act="${act}" ${data || ""}>${lab}</button>`;
const f2Year = () => { const st = UI.sub.f2 ||= {}; return st.year || String(Number(todayISO().slice(0, 4)) - (todayISO().slice(5) < "06-30" ? 1 : 0)); };
const f2YearSel = () => { const y0 = Number(todayISO().slice(0, 4)); return `<label class="pz-fc on"><span>Année civile</span><select data-ch="f2Year">${[y0, y0 - 1, y0 - 2].map(y => `<option ${String(y) === f2Year() ? "selected" : ""}>${y}</option>`).join("")}</select></label>`; };

/* ---------------- 3519 : remboursement de crédit de TVA ---------------- */
function f2Credits() { const ex = exCur(); return periodesTVA(ex).map(p => { let d = null; try { d = fxDecl(p); } catch (e) { } const credit = d && d.net < 0 ? -d.net : 0; const R = F2().remb[p.id] || {}; return { p, d, credit, R }; }); }
const f2Seuil = p => (p.type === "CA12" ? 15000 : 76000);
VIEWS.tvaRemb = () => { const L = f2Credits(); const cr = L.filter(x => x.credit > 0); const dem = cr.filter(x => x.R.demande);
  const rows = cr.map(({ p, d, credit, R }) => { const seuil = f2Seuil(p); const ok = credit >= seuil || /-12$|CA12/.test(p.id); const mt = R.montant != null ? R.montant : credit; const eD = f2EcrOf(R.ecrDem), eR = f2EcrOf(R.ecrRecu);
    return `<tr><td><b>${esc(p.lib)}</b><div class="small muted">du ${frDate(p.from)} au ${frDate(p.to)}</div></td><td class="r mono">${f2E(credit)}</td><td><label class="chk"><input type="checkbox" data-ch="f2Remb" data-p="${p.id}" data-f="demande" ${R.demande ? "checked" : ""} ${ok ? "" : "disabled"}> Demander</label>${ok ? "" : `<div class="small" style="color:#B45309">sous le seuil de ${eur0(seuil)} : crédit reporté</div>`}</td>
      <td class="r">${R.demande ? `<input class="in sm num" style="width:110px" value="${toIn(mt)}" data-ch="f2Remb" data-p="${p.id}" data-f="montant">` : "—"}</td><td class="r mono">${f2E(Math.max(0, credit - (R.demande ? mt : 0)))}</td>
      <td>${R.demande ? `<input class="in sm" type="date" value="${esc(R.date || "")}" data-ch="f2Remb" data-p="${p.id}" data-f="date">` : ""}</td>
      <td class="nowrap">${R.demande ? f2Btn(eD, "f2RembDem", "Passer l'écriture", `data-p="${p.id}"`) + " " + (eD ? f2Btn(eR, "f2RembRecu", "Remboursement reçu", `data-p="${p.id}"`) : "") : ""}</td></tr>`; }).join("");
  const tot = dem.reduce((a, x) => a + (x.R.montant != null ? x.R.montant : x.credit), 0); const recu = dem.filter(x => x.R.ecrRecu).reduce((a, x) => a + (x.R.montant != null ? x.R.montant : x.credit), 0);
  return f2Head("tvaRemb", "Demande de remboursement de crédit de TVA (formulaire 3519-SD), reliée aux déclarations CA3 ou CA12 : le crédit (ligne 23) se calcule depuis la comptabilité ; le montant demandé figure ligne 26 et le solde est reporté ligne 27.") +
    f2Kpi([["Crédits de TVA de l'exercice", cr.reduce((a, x) => a + x.credit, 0)], ["Remboursements demandés", tot], ["Remboursements reçus", recu, "ok"], ["En attente", tot - recu, tot - recu ? "ko" : ""]]) +
    `<section class="card"><div class="tw"><table class="t"><thead><tr><th>Déclaration</th><th class="r">Crédit (ligne 23)</th><th>Remboursement</th><th class="r">Montant demandé (ligne 26)</th><th class="r">Crédit reporté (ligne 27)</th><th>Date de la demande</th><th>Comptabilité</th></tr></thead><tbody>${rows || `<tr><td colspan="7" class="pz-empty">Aucune déclaration en crédit de TVA sur l'exercice.</td></tr>`}</tbody></table></div></section>
    <div class="grid g2" style="margin-top:12px;align-items:start"><section class="card"><div class="card-h"><h2>Conditions</h2></div><div class="card-b small" style="line-height:1.7"><ul style="margin:0;padding-left:18px"><li>Réel normal (CA3 mensuelle ou trimestrielle) : crédit d'au moins <b>760 €</b>.</li><li>Réel simplifié (CA12) : crédit annuel d'au moins <b>150 €</b> ; 760 € en cours d'année pour un investissement.</li><li>Dépôt avec la déclaration de TVA, en ligne sur impots.gouv.fr (espace professionnel), au plus tard le 31 décembre de la 2<sup>e</sup> année suivant la constatation du crédit.</li><li>Pièces : liste des factures, factures d'immobilisations le cas échéant.</li></ul></div></section>
    <section class="card"><div class="card-h"><h2>Écritures</h2></div><div class="card-b small" style="line-height:1.7">Demande : <span class="mono">D 445830 Remboursement de TVA demandé / C 445670 Crédit de TVA à reporter</span>.<br>Encaissement : <span class="mono">D 512 Banque / C 445830</span>, rapproché avec le relevé.</div></section></div>`; };

/* ---------------- 3514 : acomptes de TVA (régime simplifié) ---------------- */
function f2TvaAcBase() { const ex = exCur(); const pe = prevEx(ex); if (!pe) return { base: 0, pe: null }; let t = null; try { t = calcTVA(pe.debut, pe.fin); } catch (e) { } const base = t ? Math.max(0, (t.brute || 0) - (t.dABS || 0)) : 0; return { base, pe }; }
VIEWS.tvaAc = () => { const ex = exCur(); const rsi = S.regimeTVA === "RSI"; const { base, pe } = f2TvaAcBase(); const y = Number(ex.fin.slice(0, 4)); const fin2027 = ex.debut >= "2027-01-01";
  const disp = base < 100000; const A = F2().tvaAc[ex.id] ||= {}; const acs = [["juil", "Acompte de juillet", 55, ex.debut.slice(0, 4) + "-07-" + "15"], ["dec", "Acompte de décembre", 40, ex.debut.slice(0, 4) + "-12-" + "15"]];
  if (!rsi) return f2Head("tvaAc", "Acomptes semestriels de TVA du régime réel simplifié (relevé 3514).") + `<section class="card"><div class="card-b"><p style="margin-top:0"><b>Votre dossier est au régime « ${esc(({ RN_M: "réel normal mensuel", RN_T: "réel normal trimestriel", FRANCHISE: "franchise en base", EXO: "exonéré" })[S.regimeTVA] || S.regimeTVA)} » : aucun acompte de TVA n'est dû.</b> La TVA est réglée avec chaque déclaration CA3.</p><p class="small muted">Le régime simplifié de TVA est supprimé au 1er janvier 2027 : les entreprises concernées basculent au réel normal (trimestriel jusqu'à 1 M€ de chiffre d'affaires, mensuel au-delà). Aucun acompte n'est dû en décembre 2027.</p></div></section>`;
  const rows = acs.map(([k, l, pct, d]) => { const o = A[k] || {}; const calc = disp ? 0 : Math.round(base * pct / 100); const mt = o.montant != null ? o.montant : calc; const e = f2EcrOf(o.ecr); const none = fin2027;
    return `<tr><td><b>${l}</b><div class="small muted">${pct} % de la TVA de référence</div></td><td class="mono">${frDate(d)}</td><td class="r mono">${f2E(calc)}</td><td class="r"><input class="in sm num" style="width:110px" value="${toIn(mt)}" data-ch="f2TvaAc" data-k="${k}" ${none ? "disabled" : ""}></td><td>${none ? '<span class="pill n">supprimé (2027)</span>' : disp ? '<span class="pill ok">dispensé</span>' : mt ? f2Btn(e, "f2TvaAcPay", "Comptabiliser le paiement", `data-k="${k}" data-d="${d}"`) : "—"}</td></tr>`; }).join("");
  return f2Head("tvaAc", "Acomptes semestriels de TVA du régime réel simplifié (relevé 3514) : 55 % en juillet et 40 % en décembre de la TVA due au titre de l'exercice précédent (avant déduction de la TVA sur immobilisations), régularisés sur la CA12.") +
    f2Kpi([["TVA de référence " + (pe ? pe.id.replace("EX", "") : "N-1"), base], ["Acompte de juillet (55 %)", disp ? 0 : Math.round(base * 0.55)], ["Acompte de décembre (40 %)", disp ? 0 : Math.round(base * 0.4)], ["Statut", disp ? "Dispense (< 1 000 €)" : "Acomptes dus", disp ? "ok" : ""]]) +
    `<section class="card"><div class="tw"><table class="t"><thead><tr><th>Acompte</th><th>Échéance</th><th class="r">Calculé</th><th class="r">Montant versé (modulable)</th><th>Comptabilité</th></tr></thead><tbody>${rows}</tbody></table></div><div class="card-b small muted">Les acomptes versés s'imputent sur la CA12 (compte 445810). Le montant peut être réduit si l'activité baisse, sous votre responsabilité (majoration si l'écart dépasse 20 %). ${y >= 2026 ? "Le régime simplifié est supprimé au 1er janvier 2027 : pas d'acompte en décembre 2027." : ""}</div></section>`; };

/* ---------------- 2571 / 2572 : impôt sur les sociétés ---------------- */
const f2IsIS = () => { const lt = defaultLiasse(); return lt === "IS_RS" || lt === "IS_RN"; };
function f2IsPaid(ex) { return flat({ from: ex.debut, to: ex.fin }).filter(x => x.l.compte.startsWith("444") && x.e.tag !== "IS" && x.l.debit > 0).map(x => ({ date: x.e.date, m: x.l.debit, e: x.e })); }
VIEWS.isAc = () => { const ex = exCur(); const r = calcIS(ex); const A = F2().isAc[ex.id] ||= {}; const paid = f2IsPaid(ex); const cfg = cfgFiscal(); const disp = !r.acCourant;
  if (!f2IsIS()) return f2Head("isAc", "Acomptes d'impôt sur les sociétés (relevé 2571-SD).") + `<section class="card"><div class="card-b">Le dossier n'est pas soumis à l'impôt sur les sociétés : pas d'acompte d'IS.</div></section>`;
  const rows = r.acDates.map((d, i) => { const o = A[i] || {}; const calc = r.acCourant; const mt = o.montant != null ? o.montant : calc; const e = f2EcrOf(o.ecr) || (paid[i] && !o.ecr ? null : null); const p = paid.find(x => Math.abs((new Date(x.date) - new Date(d)) / 864e5) <= 20);
    return `<tr><td><b>Acompte n°${i + 1}</b></td><td class="mono">${frDate(d)}</td><td class="r mono">${f2E(calc)}</td><td class="r"><input class="in sm num" style="width:110px" value="${toIn(mt)}" data-ch="f2IsAc" data-i="${i}"></td><td>${disp ? '<span class="pill ok">dispensé</span>' : p && !o.ecr ? `<a class="lnk" data-act="viewEcr" data-id="${p.e.id}">✓ payé le ${frDate(p.date)} (${f2E(p.m)})</a>` : mt ? f2Btn(f2EcrOf(o.ecr), "f2IsAcPay", "Comptabiliser le paiement", `data-i="${i}" data-d="${d}"`) : "—"}</td></tr>`; }).join("");
  return f2Head("isAc", "Quatre acomptes trimestriels (15 mars, 15 juin, 15 septembre, 15 décembre pour un exercice civil) calculés sur l'IS du dernier exercice clos ; dispense si cet impôt n'excède pas " + eur0(cfg.seuilAcompte * 100) + ".") +
    f2Kpi([["IS de référence (exercice précédent)", r.P.isN1 || 0], ["Acompte trimestriel", r.acCourant], ["Acomptes versés sur l'exercice", r.acomptes, "ok"], ["IS estimé de l'exercice", r.is + r.cs]]) +
    `<section class="card"><div class="tw"><table class="t"><thead><tr><th>Acompte</th><th>Échéance</th><th class="r">Calculé</th><th class="r">Montant (modulable)</th><th>Comptabilité</th></tr></thead><tbody>${rows}</tbody></table></div><div class="card-b small muted">IS de référence modifiable dans « Résultat fiscal et IS ». Modulation possible du dernier acompte si l'IS estimé de l'exercice est inférieur aux acomptes déjà versés. Écriture : <span class="mono">D 444000 État – impôt sur les bénéfices / C 512 Banque</span>. Paiement en ligne obligatoire (espace professionnel).</div></section>
    ${r.cs ? `<div class="pz-note">Contribution sociale sur l'IS (3,3 %) : ${f2E(r.cs)} estimés, acomptes versés aux mêmes dates que l'IS.</div>` : ""}`; };
VIEWS.isSolde = () => { const ex = exCur(); const r = calcIS(ex); const isE = E.find(e => e.tag === "IS" && e.date >= ex.debut && e.date <= ex.fin); const A = F2().isAc[ex.id] ||= {}; const eP = f2EcrOf(A.soldeEcr);
  if (!f2IsIS()) return f2Head("isSolde", "Relevé de solde de l'impôt sur les sociétés (2572-SD).") + `<section class="card"><div class="card-b">Le dossier n'est pas soumis à l'impôt sur les sociétés.</div></section>`;
  const sol = r.is + r.cs - r.acomptes - (r.credits || 0);
  return f2Head("isSolde", "Relevé de solde 2572-SD : liquidation de l'IS de l'exercice " + esc(ex.id.replace("EX", "")) + ", imputation des acomptes et crédits d'impôt, à déposer et payer au plus tard le " + frDate(r.soldeDate) + ".") +
    f2Kpi([["Résultat fiscal", r.rf], ["IS dû", r.is + r.cs], ["Acomptes versés", r.acomptes], [sol >= 0 ? "Solde à payer" : "Excédent à rembourser", Math.abs(sol), sol > 0 ? "ko" : "ok"]]) +
    `<div class="grid g2" style="align-items:start"><section class="card"><div class="card-h"><h2>Liquidation (2572-SD)</h2></div><div class="tw"><table class="t fin-t"><tbody>${[["Résultat fiscal (2058-A)", r.rf], ["IS au taux réduit de 15 %", r.isReduit], ["IS au taux normal de 25 %", r.isNormal], ["Contribution sociale (3,3 %)", r.cs], ["Total de l'impôt", r.is + r.cs], ["− Acomptes versés (2571)", -r.acomptes], ["− Crédits d'impôt imputés", -(r.credits || 0)]].map(([l, v]) => `<tr><td>${l}</td><td class="r mono">${eur(v)}</td></tr>`).join("")}<tr class="tot"><td>${sol >= 0 ? "Solde à payer" : "Excédent (remboursement ou imputation)"}</td><td class="r mono">${eur(Math.abs(sol))}</td></tr></tbody></table></div></section>
    <section class="card"><div class="card-h"><h2>Comptabilité</h2></div><div class="card-b" style="display:flex;flex-direction:column;gap:10px"><div><b>1. Constater l'impôt de l'exercice</b><div class="small muted">D 695000 / C 444000 au ${frDate(ex.fin)}</div>${isE ? `<a class="lnk" data-act="viewEcr" data-id="${isE.id}">✓ IS comptabilisé : ${f2E(isE.lignes[0].debit)}</a>` : `<button class="btn sm pri" data-act="isBook">Comptabiliser l'IS</button>`}</div>
      <div><b>2. Payer le solde</b><div class="small muted">D 444000 / C 512000 au ${frDate(r.soldeDate)}</div>${sol > 0 ? f2Btn(eP, "f2IsSoldePay", "Comptabiliser le paiement du solde", `data-d="${r.soldeDate}" data-m="${sol}"`) : `<span class="small">Pas de solde à payer${sol < 0 ? " : demandez le remboursement de l'excédent sur le relevé 2573." : "."}</span>`}</div>
      <div class="small muted">Le prochain exercice : acomptes de ${f2E(r.acompteN1)} chacun (base : cet IS).</div></div></section></div>`; };

/* ---------------- 2777 : revenus de capitaux mobiliers (PFU) ---------------- */
const F2_PFU = () => { const f = typeof cnsRef === "function" ? cnsRef() : { pfu: 31.4, ps: 18.6 }; return { ir: Math.round((f.pfu - f.ps) * 10) / 10, ps: f.ps }; };
function f2RcmCalc(x) { const t = F2_PFU(); const brut = x.brut || 0; const pfnl = x.dispense ? 0 : Math.round(brut * t.ir / 100); const ps = x.nonRes ? 0 : Math.round(brut * t.ps / 100); return { pfnl, ps, tot: pfnl + ps, net: brut - pfnl - ps, ech: x.date ? addMonths(x.date.slice(0, 8) + "01", 1).slice(0, 8) + "15" : "" }; }
function f2RcmDetect() { const ex = exCur(); const have = new Set(F2().rcm.map(x => x.src)); const out = [];
  for (const x of flat()) { if (have.has(x.l.id)) continue; if (/^457/.test(x.l.compte) && x.l.credit > 0) out.push({ src: x.l.id, type: "div", date: x.e.date, brut: x.l.credit, benef: (x.l.aux && (tiersBy(x.l.aux) || {}).nom) || x.l.lib || x.e.libelle || "Associé" });
    else if (/^661[58]|^6615/.test(x.l.compte) && x.l.debit > 0 && x.e.lignes.some(l => /^455/.test(l.compte))) out.push({ src: x.l.id, type: "int", date: x.e.date, brut: x.l.debit, benef: x.e.lignes.find(l => /^455/.test(l.compte)).lib || x.e.libelle || "Associé" }); }
  return out.filter(o => o.date >= addMonths(ex.debut, -12)); }
VIEWS.rcm = () => { const L = F2().rcm.slice().sort((a, b) => (b.date || "").localeCompare(a.date || "")); const t = F2_PFU(); const cand = f2RcmDetect(); const ass = (jurData().associes || []).map(a => a.nom || a.denomination || "").filter(Boolean);
  const tot = L.reduce((a, x) => { const c = f2RcmCalc(x); a.b += x.brut || 0; a.t += c.tot; return a; }, { b: 0, t: 0 });
  return f2Head("rcm", "Déclaration 2777-SD des revenus de capitaux mobiliers (dividendes, intérêts de comptes courants) et paiement du prélèvement forfaitaire non libératoire de " + String(t.ir).replace(".", ",") + " % et des prélèvements sociaux de " + String(t.ps).replace(".", ",") + " % (prélèvement forfaitaire unique de " + String(Math.round((t.ir + t.ps) * 10) / 10).replace(".", ",") + " %), au plus tard le 15 du mois suivant le paiement.") +
    f2Kpi([["Revenus déclarés", tot.b], ["Prélèvements à reverser", tot.t], ["Déclarations à déposer", String(L.filter(x => !x.ecr2).length), L.some(x => !x.ecr2) ? "ko" : "ok"], ["Mouvements détectés en comptabilité", String(cand.length)]]) +
    (cand.length ? `<div class="pz-note">💡 ${cand.length} distribution(s) ou intérêt(s) de compte courant détecté(s) dans la comptabilité (comptes 457, 6615 / 455). <button class="btn sm" data-act="f2RcmImp">Reprendre dans la 2777</button></div>` : "") +
    `<section class="card"><div class="card-h"><h2>Revenus versés</h2><button class="btn sm" data-act="f2RcmAdd">+ Ajouter</button></div><div class="tw"><table class="t"><thead><tr><th>Date de paiement</th><th>Bénéficiaire</th><th>Nature</th><th class="r">Montant brut</th><th>Dispense PFNL</th><th class="r">PFNL ${String(t.ir).replace(".", ",")} %</th><th class="r">Prél. sociaux</th><th class="r">Net versé</th><th>Échéance 2777</th><th>Écritures</th><th></th></tr></thead><tbody>${L.map(x => { const c = f2RcmCalc(x); const i = F2().rcm.indexOf(x);
      return `<tr><td><input type="date" class="in sm" value="${esc(x.date || "")}" data-ch="f2Rcm" data-i="${i}" data-f="date"></td><td><input class="in sm" list="f2-ass" value="${esc(x.benef || "")}" data-ch="f2Rcm" data-i="${i}" data-f="benef" style="width:170px"></td><td><select class="in sm" data-ch="f2Rcm" data-i="${i}" data-f="type"><option value="div" ${x.type === "div" ? "selected" : ""}>Dividendes</option><option value="int" ${x.type === "int" ? "selected" : ""}>Intérêts de compte courant</option><option value="aut" ${x.type === "aut" ? "selected" : ""}>Autres produits</option></select></td><td class="r"><input class="in sm num" style="width:100px" value="${toIn(x.brut || 0)}" data-ch="f2Rcm" data-i="${i}" data-f="brut"></td><td><input type="checkbox" data-ch="f2Rcm" data-i="${i}" data-f="dispense" ${x.dispense ? "checked" : ""} title="Attestation sur l'honneur (revenu fiscal de référence < 50 000 € ou 75 000 € pour un couple)"></td><td class="r mono">${eur(c.pfnl)}</td><td class="r mono">${eur(c.ps)}</td><td class="r mono">${eur(c.net)}</td><td class="mono">${frDate(c.ech)}</td>
        <td class="nowrap">${f2Btn(f2EcrOf(x.ecr), "f2RcmEcr", "Retenue", `data-i="${i}"`)} ${f2Btn(f2EcrOf(x.ecr2), "f2RcmPay", "Paiement 2777", `data-i="${i}"`)}</td><td><button class="btn sm ghost" data-act="f2RcmDel" data-i="${i}">✕</button></td></tr>`; }).join("") || `<tr><td colspan="11" class="pz-empty">Aucun revenu de capitaux mobiliers saisi.</td></tr>`}</tbody></table></div><datalist id="f2-ass">${ass.map(a => `<option value="${esc(a)}">`).join("")}</datalist>
    <div class="card-b small muted">Écritures : retenue <span class="mono">D 457000 Associés – dividendes à payer / C 442000 État – prélèvements</span> ; paiement de la 2777 <span class="mono">D 442000 / C 512000</span> au 15 du mois suivant. Les revenus alimentent l'IFU (2561) de l'année.</div></section>`; };

/* ---------------- 2561 : IFU ---------------- */
